CREATE TABLE IF NOT EXISTS qorlla_schedules (source_id text PRIMARY KEY, legacy_code text UNIQUE NOT NULL, title text NOT NULL, owner_name text NOT NULL, scheduled_at timestamptz, status text NOT NULL DEFAULT 'pending_sync', version bigint NOT NULL DEFAULT 1, meet_uuid uuid, meet_code text, updated_at timestamptz NOT NULL DEFAULT now(), CHECK(status IN ('pending_sync','synced','cancel_pending','cancelled','sync_failed')));
CREATE TABLE IF NOT EXISTS qorlla_outbox (id bigserial PRIMARY KEY, source_id text NOT NULL REFERENCES qorlla_schedules(source_id), version bigint NOT NULL, operation text NOT NULL CHECK(operation IN ('upsert','cancel')), status text NOT NULL DEFAULT 'pending', attempts int NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, last_error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,version));
CREATE INDEX IF NOT EXISTS qorlla_outbox_due ON qorlla_outbox(next_attempt_at) WHERE status IN ('pending','leased');
CREATE TABLE IF NOT EXISTS qorlla_host_vault (source_id text PRIMARY KEY REFERENCES qorlla_schedules(source_id), ciphertext text NOT NULL, iv text NOT NULL, tag text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
